  const currentLabel=host.querySelector('#quran-current-verse');currentLabel.hidden=!active;currentLabel.textContent=active?(whole?'Сура целиком':(state.status==='paused'?'На паузе · ':state.status==='loading'?'Загрузка · ':'Читается · ')+'аят '+n):'';
